"""QQ-姿态库：白模姿态参考图选择器。

三种取图方式：固定选中 / 全库随机 / 范围内随机。视角选「随机视角」时在该姿态
可用视角里抽。库为空也能注册节点，运行时再给明确报错。
"""

from __future__ import annotations

import random
from typing import Any

import numpy as np
import torch
from PIL import Image

try:  # 包内导入（ComfyUI 正常加载）
    from . import guli_pose_db as db
except ImportError:  # pragma: no cover - 测试里按独立模块加载
    import guli_pose_db as db  # type: ignore[no-redef]

MODE_FIXED = "固定选中"
MODE_RANDOM_ALL = "全库随机"
MODE_RANDOM_FILTERED = "范围内随机"
MODES = [MODE_FIXED, MODE_RANDOM_ALL, MODE_RANDOM_FILTERED]


def _pick(
    lib: str, mode: str, label: str, angle: str, series: str, category: str
) -> dict[str, Any]:
    """通用取图：按模式在库里选一张图并返回 IMAGE。"""
    if not db.index(lib)["poses"]:
        raise db.PoseDBMissing(
            f"{db.lib_name(lib)}是空的。\n"
            "可以在节点面板里点「导入」把自己的图放进来。"
        )

    # 无种子实例化 = 每次用系统熵播种，抽到满意的姿态点一下就固定下来了
    rng = random.Random()

    if mode == MODE_FIXED:
        record = db.find_pose(label, lib)
    elif mode == MODE_RANDOM_ALL:
        record = rng.choice(db.pool(lib=lib))
    else:
        record = rng.choice(db.pool(series, category, lib))

    angle_key = db.pick_angle(record, angle, rng)
    record, real_angle, path = db.resolve(record, angle_key)

    with Image.open(path) as im:
        pixels = np.asarray(im.convert("RGB"), dtype=np.float32) / 255.0

    image = torch.from_numpy(pixels)[None, ...]
    picked = {"no": record["no"], "label": record["label"], "angle": real_angle}
    return {"ui": {"picked": [picked]}, "result": (image,)}


def _is_changed(cls, 模式="", 视角="", **_kwargs: Any) -> float | str:
    """随机模式下每次都要重新抽。

    返回 NaN 表示「每次都不一样」，强制重新执行；固定选中且视角确定时仍走缓存。
    """
    if 模式 != MODE_FIXED or 视角 == db.RANDOM_ANGLE:
        return float("nan")
    return ""


class QQGuliPosePicker:
    """白模姿态参考图选择器。姿态、视角由节点内的画廊控件挑选。"""

    CATEGORY = "QQ/图库"
    FUNCTION = "pick"
    RETURN_TYPES = ("IMAGE",)
    RETURN_NAMES = ("姿态图",)
    DESCRIPTION = (
        "从姿态库里取一张白模参考图。固定选中按名称取，全库随机/范围内随机每次重抽。"
        "视角可选五档或「随机视角」。导入的自定义图存在 ComfyUI 用户目录下，升级不会丢。"
    )
    IS_CHANGED = classmethod(_is_changed)

    @classmethod
    def INPUT_TYPES(cls) -> dict[str, Any]:
        labels = db.pose_labels() or [db.EMPTY_HINT]
        return {
            "required": {
                "模式": (MODES, {"default": MODE_FIXED}),
                "姿态": (labels, {"default": labels[0]}),
                "视角": (db.angle_choices(), {"default": "正面"}),
                "筛选系列": (db.series_options(), {"default": db.ALL}),
                "筛选分类": (db.category_options(), {"default": db.ALL}),
            }
        }

    def pick(self, 模式, 姿态, 视角, 筛选系列, 筛选分类):
        return _pick("pose", 模式, 姿态, 视角, 筛选系列, 筛选分类)


NODE_CLASS_MAPPINGS = {"QQGuliPosePicker": QQGuliPosePicker}
NODE_DISPLAY_NAME_MAPPINGS = {"QQGuliPosePicker": "QQ-姿态库"}
